+import { eventBus, type JobEvent } from "./events.ts";
+
+const NOTIFICATION_SERVICE_WEBHOOK_URL =
+  process.env.NOTIFICATION_SERVICE_WEBHOOK_URL;
+
+const MAX_RETRIES = 3;
+const RETRY_DELAY_MS = 1000;
+
+async function sendWithRetries(
+  url: string,
+  payload: JobEvent,
+  retries: number = MAX_RETRIES,
+): Promise<void> {
+  try {
+    const response = await fetch(url, {
+      method: "POST",
+      headers: { "Content-Type": "application/json" },
+      body: JSON.stringify(payload),
+    });
+
+    if (!response.ok) {
+      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
+    }
+  } catch (error) {
+    if (retries > 0) {
+      await new Promise((resolve) => setTimeout(resolve, RETRY_DELAY_MS));
+      await sendWithRetries(url, payload, retries - 1);
+    } else {
+      console.error(
+        `Failed to deliver webhook for job ${payload.id}:`,
+        error,
+      );
+    }
+  }
+}
+
+export const setupWebhookPublisher = () => {
+  if (!NOTIFICATION_SERVICE_WEBHOOK_URL) {
+    console.log(
+      "NOTIFICATION_SERVICE_WEBHOOK_URL not set; webhook publisher disabled",
+    );
+    return;
+  }
+
+  eventBus.subscribe(async (event: JobEvent) => {
+    if (event.type === "job.enqueued") {
+      await sendWithRetries(NOTIFICATION_SERVICE_WEBHOOK_URL, event);
+    }
+  });
+};
